// Build index.html (self-contained playground) from playground.src.html,
// dfam.js and presets/*.txt:   node js/build-standalone.mjs
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
const here = (f) => new URL(f, import.meta.url);
const strip = (src) => src.replace(/^export /gm, '');
const presets = {};
for (const f of readdirSync(here('../presets/')).filter((f) => f.endsWith('.txt')).sort())
  presets[f.replace(/\.txt$/, '')] = readFileSync(here('../presets/' + f), 'utf8');
writeFileSync(here('./presets.js'),
  '// Generated by build-standalone.mjs from presets/*.txt\nexport const PRESETS = ' + JSON.stringify(presets, null, 2) + ';\n');
const html = readFileSync(here('./playground.src.html'), 'utf8')
  .replace('/*@ENGINE@*/', () => '\n' + strip(readFileSync(here('./dfam.js'), 'utf8')).replaceAll('</script', '<\\/script'))
  .replace('/*@PRESETS@*/', () => 'const PRESETS = ' + JSON.stringify(presets) + ';');
writeFileSync(here('./index.html'), html);
console.log('wrote js/index.html and js/presets.js; presets:', Object.keys(presets).join(', '));
